<script setup>
import { computed, ref, watch } from 'vue';
import OntologyScenarioPanel from './OntologyScenarioPanel.vue';
import OntologyCaseReplay from './OntologyCaseReplay.vue';
import OntologyReadPlanPanel from './OntologyReadPlanPanel.vue';
import OntologyMappingWizard from './OntologyMappingWizard.vue';
import OntologyGraph from './OntologyGraph.vue';
import { createOntologyEditSession } from './ontology-edit-session.js';

const props = defineProps({ metaModel: Object, draft: Object, authoringProfile: Object, simulation: Object, semanticContext: Object, role: String, message: String, replayCases: Function, knowledgeClient: Object, focusedObjectId: String, savedLayout: Object, buttonPermissionIds: { type: Array, default: () => [] } });
const emit = defineEmits(['save-draft', 'validate-draft', 'simulate-build', 'publish', 'ask', 'select-object', 'save-layout']);
const localDraft = ref(null); const selectedId = ref(''); const relationFrom = ref(''); const relationTo = ref(''); const relationLabel = ref('关联'); const draggingId = ref('');
const savedDraftShape = ref('');
const editSession = createOntologyEditSession();
const historyCounts = ref({ undo: 0, redo: 0 });
const advancedOpen = ref(false); const workspaceNotice = ref(''); let restoring = false;
function restoreEdit(direction) {
  if (!canModel.value || !localDraft.value) return;
  editSession.record(localDraft.value);
  const restored = editSession[direction]();
  if (restored) { restoring = true; localDraft.value = restored; restoring = false; }
  historyCounts.value = editSession.counts();
}
watch(localDraft, value => { if (!restoring && value) { editSession.record(value); historyCounts.value = editSession.counts(); } }, { deep: true, flush: 'sync' });
const hasUnsavedChanges = computed(() => Boolean(localDraft.value) && JSON.stringify(localDraft.value) !== savedDraftShape.value);
const reviewMode = ref('objects');
const paletteQuery = ref('');
const canModel = computed(() => props.authoringProfile?.canModel === true && props.buttonPermissionIds.includes('meta_model.draft.save'));
const canValidate = computed(() => props.authoringProfile?.canModel === true && props.buttonPermissionIds.includes('meta_model.draft.validate'));
const canSimulate = computed(() => props.authoringProfile?.canModel === true && props.buttonPermissionIds.includes('meta_model.simulate'));
const canPublish = computed(() => props.authoringProfile?.canPublish === true && props.buttonPermissionIds.includes('meta_model.publish'));
watch(() => props.focusedObjectId, id => { if (localDraft.value?.objectTypes.some(item => item.id === id)) selectedId.value = id; });
const selectedObject = computed(() => localDraft.value?.objectTypes?.find((item) => item.id === selectedId.value));
const selectedRelationKey = ref('');
const diagnosticSelection = ref(null); const diagnosticText = ref(''); const diagnosticBase = ref('');
const diagnosticSections = ['readPlans', 'decisionBindings', 'actionBindings', 'stateMachines', 'metrics', 'dataContracts', 'qualityRules', 'glossaryTerms', 'accessPolicies', 'lineageEdges'];
function diagnosticArray(target) { return ['readPlans', 'decisionBindings', 'actionBindings'].includes(target.section) ? localDraft.value?.scenario?.[target.section] : localDraft.value?.[target.section]; }
function validDiagnostic(target) { return target.kind === 'section' && diagnosticSections.includes(target.section) && Number.isInteger(target.index) && (target.index === -1 ? Array.isArray(diagnosticArray(target)) : target.index >= 0 && Boolean(diagnosticArray(target)?.[target.index])); }
function applyDiagnosticEdit() {
  if (!canModel.value || !diagnosticSelection.value || diagnosticBase.value !== JSON.stringify(localDraft.value) || !validDiagnostic(diagnosticSelection.value)) { workspaceNotice.value = '模型或权限已变更，请重新选择当前校验问题。'; return; }
  try {
    if (diagnosticText.value.length > 80000) throw new Error('修改项超过80KB。');
    const value = JSON.parse(diagnosticText.value); const collection = diagnosticSelection.value.index === -1;
    if (collection ? !Array.isArray(value) || value.some(item => !item || typeof item !== 'object' || Array.isArray(item)) : !value || typeof value !== 'object' || Array.isArray(value)) throw new Error(collection ? '集合必须是JSON对象数组。' : '配置项必须为JSON对象。');
    const candidate = clone(localDraft.value); const target = diagnosticSelection.value;
    const array = ['readPlans', 'decisionBindings', 'actionBindings'].includes(target.section) ? candidate.scenario[target.section] : candidate[target.section];
    if (collection) { if (['readPlans', 'decisionBindings', 'actionBindings'].includes(target.section)) candidate.scenario[target.section] = value; else candidate[target.section] = value; }
    else array[target.index] = value;
    localDraft.value = candidate; diagnosticSelection.value = null;
    workspaceNotice.value = '仅修改本地选定配置项；请保存并重新校验、回放，不会自动发布。';
  } catch (error) { workspaceNotice.value = error.message; }
}
const selectedRelation = computed(() => localDraft.value?.relationshipTypes.find(item => JSON.stringify([item.from, item.predicate, item.to]) === selectedRelationKey.value));
function editRelation(relation) { selectedRelationKey.value = JSON.stringify([relation.from, relation.predicate, relation.to]); relationFrom.value = relation.from; relationTo.value = relation.to; reviewMode.value = 'relations'; advancedOpen.value = true; }
function askFromWorkspace(question) {
  if (hasUnsavedChanges.value) { workspaceNotice.value = '请先保存本次草稿再向 Agent 提问，避免 Agent 使用旧修订解释当前未保存模型。'; return; }
  emit('ask', question);
}
function applyMappingDraft(candidate) {
  if (!canModel.value || candidate?.baseShape !== JSON.stringify(localDraft.value)) { workspaceNotice.value = '角色或模型已经变化，请重新配置映射。'; return; }
  localDraft.value = clone(candidate.draft);
  workspaceNotice.value = '主数据映射已加入本地候选；请保存、校验与回放，不会自动发布。';
}
const simulation = computed(() => props.simulation?.instances ? props.simulation : null);
const fallbackPalette = [
  { id: 'PurchaseDemand', label: '采购需求', source: 'erp.purchase_demand', key: 'demand_id', fields: ['demand_id', 'material_code', 'qty', 'required_date', 'status'], classification: '运营受限' },
  { id: 'QualityReview', label: '质量复核', source: 'qms.quality_review', key: 'review_id', fields: ['review_id', 'business_ref', 'reviewer_id', 'decision', 'status'], classification: '质量受限' },
  { id: 'BudgetCheck', label: '预算校验', source: 'erp.budget_check', key: 'check_id', fields: ['check_id', 'business_ref', 'amount', 'decision', 'status'], classification: '财务受限' },
  { id: 'NotificationReceipt', label: '通知回执', source: 'oa.notification_receipt', key: 'receipt_id', fields: ['receipt_id', 'notice_id', 'recipient_id', 'read_at', 'status'], classification: '内部受限' }
];
const semanticDiscovery = computed(() => props.authoringProfile?.semanticDiscovery || null);
const palette = computed(() => semanticDiscovery.value?.candidateObjects?.length ? semanticDiscovery.value.candidateObjects.map((item) => ({
  ...item,
  source: `${item.sourceSystems?.[0]?.toLowerCase() || 'semantic'}.observed_${item.id.toLowerCase()}`,
  key: `${item.id.replace(/([a-z])([A-Z])/g, '$1_$2').toLowerCase()}_id`, semanticType: item.id
})) : fallbackPalette);
const filteredPalette = computed(() => {
  const keyword = paletteQuery.value.trim().toLowerCase();
  if (!keyword) return palette.value;
  return palette.value.filter((item) => [item.label, item.id, item.coreObject, item.classification, ...(item.sourceSystems || [])].filter(Boolean).some((value) => String(value).toLowerCase().includes(keyword)));
});
const objectHealth = (item) => {
  const missing = [];
  if (!item.label?.trim()) missing.push('业务名称');
  if (!item.key?.trim()) missing.push('业务主键');
  if (!item.source?.trim()) missing.push('数据来源');
  if (!item.sourceSystems?.length || item.sourceSystems.some((value) => String(value).includes('待观察'))) missing.push('来源系统');
  if (!item.fields?.length) missing.push('业务字段');
  if (!item.coreObject?.trim()) missing.push('元对象锚点');
  return { complete: missing.length === 0, missing };
};
const invalidRelations = computed(() => (localDraft.value?.relationshipTypes || []).filter((relation) => !localDraft.value.objectTypes.some((item) => item.id === relation.from) || !localDraft.value.objectTypes.some((item) => item.id === relation.to) || !relation.predicate?.trim()));
const externalConflictCount = computed(() => Number(props.semanticContext?.metrics?.openConflicts || 0));
const reviewIssues = computed(() => {
  const issues = (localDraft.value?.objectTypes || []).filter((item) => !objectHealth(item).complete).map((item) => ({ id: `object-${item.id}`, kind: 'object', targetId: item.id, title: `${item.label || item.id} 信息不完整`, detail: `待补：${objectHealth(item).missing.join('、')}`, severity: 'warning' }));
  invalidRelations.value.forEach((item, index) => issues.push({ id: `relation-${index}`, kind: 'relation', from: item.from, predicate: item.predicate, to: item.to, title: '关系引用不完整', detail: `${item.from || '未选择'} —${item.predicate || '未命名'}→ ${item.to || '未选择'}`, severity: 'error' }));
  if (!hasUnsavedChanges.value) (localDraft.value?.validation?.checks || []).filter((check) => check.status !== 'passed').forEach((check, index) => {
    const targets = (check.targets || []).filter(target => target.kind === 'object' ? localDraft.value.objectTypes.some(object => object.id === target.targetId) : target.kind === 'section' ? validDiagnostic(target) : target.kind === 'relation' && localDraft.value.relationshipTypes.some(relation => relation.from === target.from && relation.to === target.to && relation.predicate === target.predicate));
    if (!targets.length) issues.push({ id: `validation-${index}`, kind: 'validation', title: check.name, detail: check.detail, severity: 'error' });
    else targets.forEach((target, n) => issues.push({ ...target, id: `validation-${index}-${n}`, title: `${check.name} · ${target.field}`, detail: check.detail, severity: 'error' }));
  });
  if (externalConflictCount.value) issues.push({ id: 'semantic-context-conflicts', kind: 'context', title: `语义上下文存在 ${externalConflictCount.value} 项开放冲突`, detail: '这些冲突来自受控事实层，发布前需要进入风险闭环复核；它们不等同于对象结构错误。', severity: 'warning' });
  return issues;
});
const completeObjectCount = computed(() => (localDraft.value?.objectTypes || []).filter((item) => objectHealth(item).complete).length);
const reviewProgress = computed(() => {
  const total = (localDraft.value?.objectTypes?.length || 0) + (localDraft.value?.relationshipTypes?.length || 0) + 1 + externalConflictCount.value;
  const ready = completeObjectCount.value + Math.max(0, (localDraft.value?.relationshipTypes?.length || 0) - invalidRelations.value.length) + (localDraft.value?.validation?.status === 'passed' ? 1 : 0);
  return total ? Math.round((ready / total) * 100) : 0;
});
const objectLabel = (id) => localDraft.value?.objectTypes?.find((item) => item.id === id)?.label || id;
const jumpToIssue = (issue) => {
  advancedOpen.value = true;
  if (issue.kind === 'object') { selectedId.value = issue.targetId; reviewMode.value = 'objects'; }
  else if (validDiagnostic(issue)) { diagnosticSelection.value = clone(issue); diagnosticText.value = JSON.stringify(issue.index === -1 ? diagnosticArray(issue) : diagnosticArray(issue)[issue.index], null, 2); diagnosticBase.value = JSON.stringify(localDraft.value); reviewMode.value = 'issues'; workspaceNotice.value = `定位到 ${issue.section}${issue.index === -1 ? '集合' : `[${issue.index}]`} · ${issue.datasetId || issue.outputId || issue.field}；仅编辑该项，不猜测其他配置。`; }
  else if (issue.kind === 'relation') { const relation = localDraft.value.relationshipTypes.find(item => item.from === issue.from && item.to === issue.to && item.predicate === issue.predicate); if (relation) editRelation(relation); else selectedRelationKey.value = ''; relationFrom.value = issue.from || ''; relationTo.value = issue.to || ''; selectedId.value = issue.from || issue.to || ''; reviewMode.value = 'relations'; workspaceNotice.value = issue.detail; }
  else { reviewMode.value = 'issues'; workspaceNotice.value = '服务端校验未提供精确目标，请查看校验详情；不会猜测对象归属。'; }
};

const clone = (value) => JSON.parse(JSON.stringify(value));
watch([() => props.draft, () => props.role, () => props.knowledgeClient, canModel], ([draft]) => {
  if (hasUnsavedChanges.value) workspaceNotice.value = '服务端模型或当前角色已变化，本次未保存编辑和撤销历史已清空，请重新核对。';
  restoring = true;
  selectedRelationKey.value = '';
  diagnosticSelection.value = null;
  if (!draft) { localDraft.value = null; editSession.reset(null); historyCounts.value = editSession.counts(); restoring = false; return; }
  localDraft.value = clone(draft);
  localDraft.value.modelingProfile ||= 'oa-approval';
  localDraft.value.scenario ||= { objective: '', questions: [], decisionBindings: [], actionBindings: [] };
  localDraft.value.objectTypes.forEach(item => { item.granularity ||= 'unspecified'; });
  localDraft.value.relationshipTypes.forEach(item => { item.provenanceType ||= 'declared'; });
  savedDraftShape.value = JSON.stringify(localDraft.value);
  editSession.reset(localDraft.value); historyCounts.value = editSession.counts(); restoring = false;
  if (!selectedId.value || !draft.objectTypes.some((item) => item.id === selectedId.value)) selectedId.value = draft.objectTypes[0]?.id || '';
  relationFrom.value = draft.objectTypes[0]?.id || '';
  relationTo.value = draft.objectTypes[1]?.id || '';
}, { immediate: true, deep: true });

const createCustomObject = () => {
  if (!canModel.value || !localDraft.value) return;
  const suffix = localDraft.value.objectTypes.filter((item) => item.id.startsWith('BusinessObject')).length + 1;
  const id = `BusinessObject${suffix}`;
  localDraft.value.objectTypes.push({ id, label: '新业务对象', source: 'oa.custom_business_object', key: `business_object_${suffix}_id`, fields: [`business_object_${suffix}_id`, 'name', 'status'], classification: '内部受限', semanticType: id, coreObject: id, sourceSystems: ['OA'], description: '' });
  selectedId.value = id;
};
const addPreset = (preset) => {
  if (!canModel.value || !localDraft.value || localDraft.value.objectTypes.some((item) => item.id === preset.id)) return;
  localDraft.value.objectTypes.push({ ...clone(preset), sourceSystems: preset.sourceSystems || [String(preset.source || 'oa').split('.')[0].toUpperCase()], coreObject: preset.coreObject || preset.id, semanticType: preset.semanticType || preset.id, description: preset.description || '' }); selectedId.value = preset.id;
};
const removeObject = (id) => {
  if (!canModel.value || !localDraft.value) return;
  localDraft.value.objectTypes = localDraft.value.objectTypes.filter((item) => item.id !== id);
  localDraft.value.relationshipTypes = localDraft.value.relationshipTypes.filter((item) => item.from !== id && item.to !== id);
  selectedId.value = localDraft.value.objectTypes[0]?.id || '';
};
const setFields = (value) => { if (selectedObject.value) selectedObject.value.fields = value.split(/[，,\n]/).map((item) => item.trim()).filter(Boolean); };
const setSourceSystems = (value) => { if (selectedObject.value) selectedObject.value.sourceSystems = value.split(/[，,\n]/).map((item) => item.trim().toUpperCase()).filter(Boolean); };
const addRelation = () => {
  if (!canModel.value || !localDraft.value || !relationFrom.value || !relationTo.value) return;
  const predicate = relationLabel.value.trim().replace(/[^\u4e00-\u9fa5A-Za-z0-9_]/g, '') || '关联';
  const exists = localDraft.value.relationshipTypes.some((item) => item.from === relationFrom.value && item.to === relationTo.value && item.predicate === predicate);
  if (!exists) localDraft.value.relationshipTypes.push({ from: relationFrom.value, to: relationTo.value, predicate, label: `${relationFrom.value} ${predicate} ${relationTo.value}`, cardinality: '1:n', evidence: '人工建模' });
};
const addSuggestedRelation = (relation) => {
  if (!canModel.value || !localDraft.value || !localDraft.value.objectTypes.some((item) => item.id === relation.from) || !localDraft.value.objectTypes.some((item) => item.id === relation.to)) return;
  if (!localDraft.value.relationshipTypes.some((item) => item.from === relation.from && item.to === relation.to && item.predicate === relation.predicate)) localDraft.value.relationshipTypes.push({ ...relation, cardinality: 'n:n', evidence: `Semantica 观察到 ${relation.evidenceCount || 0} 个共享业务标识` });
};
const removeRelation = (index) => { if (canModel.value) localDraft.value.relationshipTypes.splice(index, 1); };
const semanticAssetDefaults = {
  metrics: () => ({ id: `metric_${Date.now().toString(36)}`, label: '新业务指标', description: '', grain: localDraft.value.objectTypes[0]?.id || '', aggregation: 'count', expression: 'count(*)', unit: 'count' }),
  glossaryTerms: () => ({ id: `term_${Date.now().toString(36)}`, term: '新业务术语', definition: '', steward: '', objectType: localDraft.value.objectTypes[0]?.id || '' }),
  dataContracts: () => ({ id: `contract_${Date.now().toString(36)}`, sourceSystem: 'OA', objectType: localDraft.value.objectTypes[0]?.id || '', schemaVersion: '1.0', freshnessMinutes: 60, availabilitySlo: 99.9, owner: '' }),
  qualityRules: () => ({ id: `quality_${Date.now().toString(36)}`, objectType: localDraft.value.objectTypes[0]?.id || '', field: '', rule: 'not_null', severity: 'error', threshold: 1 }),
  accessPolicies: () => ({ id: `access_${Date.now().toString(36)}`, objectType: localDraft.value.objectTypes[0]?.id || '', effect: 'allow', roles: [], condition: '', maskedFields: [] }),
  lineageEdges: () => ({ from: 'OA.source_object', to: localDraft.value.objectTypes[0]?.id || '', transformation: 'canonical_mapping', fields: [] })
};
const addSemanticAsset = (type) => { if (canModel.value) (localDraft.value[type] ||= []).push(semanticAssetDefaults[type]()); };
const removeSemanticAsset = (type, index) => { if (canModel.value) localDraft.value[type].splice(index, 1); };
const setArrayValue = (target, key, value) => { target[key] = String(value || '').split(/[，,\n]/).map((item) => item.trim()).filter(Boolean); };
const reorder = (targetId) => {
  if (!canModel.value || !draggingId.value || draggingId.value === targetId) return;
  const items = localDraft.value.objectTypes; const from = items.findIndex((item) => item.id === draggingId.value); const to = items.findIndex((item) => item.id === targetId);
  if (from >= 0 && to >= 0) items.splice(to, 0, items.splice(from, 1)[0]);
  draggingId.value = '';
};
const saveDraft = () => { if (!canModel.value || !localDraft.value) return; emit('save-draft', { modelingProfile: localDraft.value.modelingProfile, scenario: localDraft.value.scenario, stateMachines: localDraft.value.stateMachines, events: localDraft.value.events, objectTypes: localDraft.value?.objectTypes || [], relationshipTypes: localDraft.value?.relationshipTypes || [], policies: localDraft.value?.policies || [], metrics: localDraft.value?.metrics || [], glossaryTerms: localDraft.value?.glossaryTerms || [], dataContracts: localDraft.value?.dataContracts || [], qualityRules: localDraft.value?.qualityRules || [], accessPolicies: localDraft.value?.accessPolicies || [], lineageEdges: localDraft.value?.lineageEdges || [] }); };
</script>

<template>
  <section v-if="metaModel && localDraft" class="panel meta-model-studio">
    <div class="edit-session-toolbar"><b>语义模型工作区 · {{ hasUnsavedChanges ? '本地未保存草稿' : '当前服务端草稿' }}</b><button :disabled="!canModel || !historyCounts.undo" @click="restoreEdit('undo')">撤销 {{ historyCounts.undo }}</button><button :disabled="!canModel || !historyCounts.redo" @click="restoreEdit('redo')">重做 {{ historyCounts.redo }}</button><small>最多50步，仅本次编辑；不回滚已发布版本。</small></div>
    <p v-if="workspaceNotice" role="status">{{ workspaceNotice }}</p>
    <button class="edit-open-button" :disabled="!selectedObject" @click="advancedOpen = true; reviewMode = 'objects'">{{ canModel ? '修改选中对象' : '查看选中对象配置' }}</button>
    <section v-if="selectedRelation" class="edit-session-toolbar" aria-label="选中关系修改"><b>{{ objectLabel(selectedRelation.from) }} → {{ objectLabel(selectedRelation.to) }}</b><label>关系名称<input v-model="selectedRelation.label" :disabled="!canModel" /></label><label>关系基数<select v-model="selectedRelation.cardinality" :disabled="!canModel"><option>1:1</option><option>1:n</option><option>n:1</option><option>n:n</option></select></label><label>依据说明<input v-model="selectedRelation.evidence" :disabled="!canModel" /></label><small>仅修改本次草稿，不自动采纳、校验或发布。</small></section>
    <OntologyGraph :objects="localDraft.objectTypes" :relationships="localDraft.relationshipTypes" :selected-id="selectedId" :model-fingerprint="hasUnsavedChanges ? '' : draft?.fingerprint" :saved-layout="hasUnsavedChanges ? null : savedLayout" title="语义模型关系图 · 本次编辑" @save-layout="emit('save-layout', $event)" @select-object="selectedId = $event; emit('select-object', $event)" @select-relationship="editRelation" @ask="askFromWorkspace" />
    <div class="workspace-issues" aria-label="模型校对问题"><button v-for="issue in reviewIssues" :key="issue.id" @click="jumpToIssue(issue)">{{ issue.title }} · {{ issue.kind === 'object' || issue.kind === 'relation' ? '定位并处理' : '查看详情' }}</button></div>
    <details :open="advancedOpen" class="workspace-advanced" @toggle="advancedOpen = $event.target.open"><summary>按需修改对象、关系和技术映射</summary>
    <section v-if="diagnosticSelection" class="diagnostic-editor" aria-label="校验问题配置项"><b>{{ diagnosticSelection.section }}{{ diagnosticSelection.index === -1 ? '集合' : `[${diagnosticSelection.index}]` }} · {{ diagnosticSelection.field }}</b><textarea v-model="diagnosticText" :disabled="!canModel" aria-label="选定配置项JSON"/><button :disabled="!canModel || diagnosticBase !== JSON.stringify(localDraft)" @click="applyDiagnosticEdit">将此项修改加入本地草稿</button><button @click="diagnosticSelection = null">关闭</button></section>
    <OntologyScenarioPanel :draft="localDraft" :can-edit="canModel" :profile="authoringProfile" :selected-object="selectedObject" :simulation="simulation" @replace-draft="localDraft = $event; selectedId = $event.objectTypes[0]?.id || ''" @change-profile="localDraft.modelingProfile = $event" @change-granularity="selectedObject.granularity = $event" />
    <OntologyReadPlanPanel :draft="localDraft" :can-edit="canModel" :client="knowledgeClient" :saved-fingerprint="draft?.fingerprint" :has-unsaved-changes="hasUnsavedChanges" @apply-plan="localDraft.scenario.readPlans = $event; localDraft.scenario.requireCaseReplay = true" />
    <OntologyMappingWizard :draft="localDraft" :can-edit="canModel" @apply-draft="applyMappingDraft" />
    <OntologyCaseReplay :fingerprint="draft?.fingerprint" :role="role" :read-plan-mode="Boolean(localDraft.scenario?.readPlans?.length)" :disabled="!canValidate || hasUnsavedChanges" :execute="replayCases" />
    <p v-if="hasUnsavedChanges" role="status">有未保存修改。请先保存，再校验、模拟构建或登记；旧版本的通过结果不适用于当前编辑。</p>
    <div class="section-header"><div><span class="eyebrow">SEMANTIC META MODEL WORKBENCH · SEMANTICA</span><h2>可视化语义建模</h2><p>候选对象和关系来自 Semantica 图谱；将它们加入画布、补齐业务规则后，再登记为智脑可用的语义模型。</p></div><div class="meta-status"><b>{{ canModel ? '可编辑' : '只读查看' }}</b><small>{{ metaModel.code }} · 草稿 {{ localDraft.id }}</small></div></div>
    <div class="authoring-steps review-journey"><span class="done"><i>1</i><b>观察事实</b><small>Semantica 候选</small></span><em>›</em><button :class="{ active: reviewMode === 'objects' }" @click="reviewMode = 'objects'"><i>2</i><b>校对对象</b><small>{{ completeObjectCount }}/{{ localDraft.objectTypes.length }} 完整</small></button><em>›</em><button :class="{ active: reviewMode === 'relations' }" @click="reviewMode = 'relations'"><i>3</i><b>校对关系</b><small>{{ localDraft.relationshipTypes.length - invalidRelations.length }}/{{ localDraft.relationshipTypes.length }} 有效</small></button><em>›</em><button :class="{ active: reviewMode === 'issues' }" @click="reviewMode = 'issues'"><i>4</i><b>处理问题</b><small>{{ reviewIssues.length }} 项待处理</small></button><em>›</em><span :class="{ done: localDraft.validation?.status === 'passed' }"><i>5</i><b>校验登记</b><small>{{ localDraft.validation?.status === 'passed' ? '可以模拟构建' : '等待校验' }}</small></span></div>

    <section class="semantic-discovery" :class="semanticDiscovery?.status || 'unavailable'"><div><span>SEMANTICA MODEL DISCOVERY</span><b>语义候选对象库</b><p>{{ semanticDiscovery?.status === 'observed' ? `已从 ${semanticDiscovery.observedRunCount} 个演练运行的 Semantica 图中抽取对象类型、字段和关系证据。` : semanticDiscovery?.status === 'template_only' ? '尚未入图演练事实；当前展示平台语义契约模板，启动模拟场景后会显示实际观察证据。' : 'Semantica 暂不可用；当前显示受控的本地业务对象模板，不能代表语义图已验证。' }}</p></div><div class="semantic-discovery-metrics"><b>{{ semanticDiscovery?.graph?.node_count || 0 }}</b><small>图节点</small><b>{{ semanticDiscovery?.candidateRelationships?.length || 0 }}</b><small>观察关系</small><b>{{ semanticDiscovery?.modelDeployment?.status === 'published' ? '已登记' : '待登记' }}</b><small>模型状态</small></div></section>
    <p class="semantic-connection-note"><b>关联路径：</b>Semantica 事实图 → 候选对象/关系 → 当前草稿画布 → 校验通过的模型定义 → Semantica 模型登记。候选仅包含结构与证据计数，不复制原始业务数据。</p>

    <section class="review-overview"><div class="review-progress"><header><div><span>REVIEW READINESS</span><b>人工校对完成度</b></div><strong>{{ reviewProgress }}%</strong></header><div><i :style="{ width: `${reviewProgress}%` }"/></div><p>对象结构、关系引用与校验结果共同决定完成度；未完成项不会被隐藏。</p></div><article><span>对象完整性</span><b>{{ completeObjectCount }}<small>/{{ localDraft.objectTypes.length }}</small></b><em :class="completeObjectCount === localDraft.objectTypes.length ? 'passed' : 'warning'">{{ completeObjectCount === localDraft.objectTypes.length ? '全部完整' : '需要补齐' }}</em></article><article><span>关系有效性</span><b>{{ localDraft.relationshipTypes.length - invalidRelations.length }}<small>/{{ localDraft.relationshipTypes.length }}</small></b><em :class="invalidRelations.length ? 'danger' : 'passed'">{{ invalidRelations.length ? `${invalidRelations.length} 条异常` : '引用有效' }}</em></article><article><span>待处理问题</span><b>{{ reviewIssues.length }}</b><em :class="reviewIssues.length ? 'warning' : 'passed'">{{ reviewIssues.length ? '逐项处理' : '没有阻塞' }}</em></article></section>

    <label v-if="reviewMode === 'objects' && selectedObject" class="domain-editor">所选对象业务域<input v-model="selectedObject.businessDomain" :disabled="!canModel" maxlength="48" placeholder="例如采购、生产、财务；留空为未归类"/><small>人工归类，仅用于模型组织；不授予数据权限。</small></label>
    <div v-if="reviewMode === 'objects'" class="business-modeler review-object-workbench">
      <aside class="model-palette"><header><div><span>候选对象</span><b>来自 Semantica</b></div><small>{{ filteredPalette.length }} 个候选</small></header><input v-model="paletteQuery" class="palette-search" placeholder="搜索名称、编码、来源系统"/><div class="palette-list"><button v-for="item in filteredPalette" :key="item.id" type="button" :disabled="!canModel || localDraft.objectTypes.some((object) => object.id === item.id)" @click="addPreset(item)"><b>{{ localDraft.objectTypes.some((object) => object.id === item.id) ? '✓' : '＋' }}</b><div><strong>{{ item.label }}</strong><small>{{ item.id }}</small><em>{{ item.coreObject || item.classification }} · {{ item.observedFacts ? `${item.observedFacts} 条证据` : item.classification }}</em></div></button></div><button type="button" class="new-object" :disabled="!canModel" @click="createCustomObject"><b>＋</b><div><strong>自定义业务对象</strong><small>从空白对象开始</small></div></button><p>这里只加入字段结构和证据摘要，不复制业务明细。</p></aside>
      <section class="model-canvas" aria-label="元模型业务对象校对列表"><div class="canvas-toolbar"><div><span>草稿对象</span><small>选择卡片，在右侧逐项校对</small></div><b>{{ localDraft.objectTypes.length }} 个对象</b></div><div class="model-node-grid"><button v-for="item in localDraft.objectTypes" :key="item.id" type="button" draggable="true" :class="['model-node-card', { selected: selectedId === item.id, incomplete: !objectHealth(item).complete }]" @dragstart="draggingId = item.id" @dragover.prevent @drop="reorder(item.id)" @click="selectedId = item.id"><span>{{ item.classification }}</span><b>{{ item.label }}</b><small>{{ item.id }}</small><div><em>{{ item.fields.length }} 个字段</em><strong>{{ item.sourceSystems?.join(' / ') || '未设置来源' }}</strong></div><i>{{ objectHealth(item).complete ? '✓ 完整' : `! 缺少 ${objectHealth(item).missing.length} 项` }}</i></button></div></section>
      <aside class="property-inspector"><template v-if="selectedObject"><header><div><span>当前校对对象</span><b>{{ selectedObject.label }}</b><small>{{ selectedObject.id }}</small></div><em :class="objectHealth(selectedObject).complete ? 'passed' : 'warning'">{{ objectHealth(selectedObject).complete ? '结构完整' : `待补 ${objectHealth(selectedObject).missing.length} 项` }}</em></header><div v-if="!objectHealth(selectedObject).complete" class="missing-fields"><b>校对提示</b><span v-for="item in objectHealth(selectedObject).missing" :key="item">{{ item }}</span></div><div class="inspector-form"><label>业务名称<input v-model="selectedObject.label" :disabled="!canModel"/></label><label>稳定对象编码<input :value="selectedObject.id" disabled/><small>编码发布后不可随意改变。</small></label><label>核心元对象锚点<select v-model="selectedObject.coreObject" :disabled="!canModel"><option v-for="anchor in [...new Set([selectedObject.id, selectedObject.coreObject, 'Person', 'RawMaterial', 'Product', 'Equipment', 'Store'])]" :key="anchor" :value="anchor">{{ anchor === selectedObject.id ? `${anchor}（独立类型）` : anchor }}</option></select></label><label>数据分级<select v-model="selectedObject.classification" :disabled="!canModel"><option>内部</option><option>内部受限</option><option>个人信息受限</option><option>质量受限</option><option>财务受限</option><option>运营受限</option></select></label><label class="wide">数据来源<input v-model="selectedObject.source" :disabled="!canModel"/></label><label>来源系统<textarea :value="selectedObject.sourceSystems?.join('，')" :disabled="!canModel" @input="setSourceSystems($event.target.value)"/></label><label>业务主键<input v-model="selectedObject.key" :disabled="!canModel"/></label><label class="wide">业务字段<textarea :value="selectedObject.fields.join('，')" :disabled="!canModel" @input="setFields($event.target.value)"/><small>使用逗号或换行分隔，至少保留业务主键和状态字段。</small></label><label class="wide">业务说明<textarea v-model="selectedObject.description" :disabled="!canModel"/></label></div><footer><button type="button" class="delete-object" :disabled="!canModel" @click="removeObject(selectedObject.id)">移除对象</button><button type="button" class="next-review" @click="reviewMode = 'relations'">下一步：校对关系 →</button></footer></template><p v-else>从中间选择一个业务对象开始校对。</p></aside>
    </div>

    <section v-else-if="reviewMode === 'relations'" class="relation-review-workbench"><div class="relation-visual"><p>关系图已统一到上方工作区。点击连线可定位本次关系，并查看依据或向 Agent 提出修改。</p></div><aside class="relation-panel"><header><span>关系校对</span><b>{{ localDraft.relationshipTypes.length }} 条草稿关系</b></header><section class="relation-composer"><label>起点对象<select v-model="relationFrom" :disabled="!canModel"><option v-for="item in localDraft.objectTypes" :key="item.id" :value="item.id">{{ item.label }}</option></select></label><label>关系语义<input v-model="relationLabel" :disabled="!canModel" placeholder="例如：发起、审批、归属"/></label><label>终点对象<select v-model="relationTo" :disabled="!canModel"><option v-for="item in localDraft.objectTypes" :key="item.id" :value="item.id">{{ item.label }}</option></select></label><button type="button" class="primary-button" :disabled="!canModel" @click="addRelation">＋ 添加关系</button></section><div class="editable-relation-list"><article v-for="(item, index) in localDraft.relationshipTypes" :key="`${item.from}-${item.predicate}-${item.to}-${index}`"><div><b>{{ objectLabel(item.from) }}</b><span>{{ item.from }}</span></div><i>— {{ item.predicate }} →</i><div><b>{{ objectLabel(item.to) }}</b><span>{{ item.to }}</span></div><em>{{ item.cardinality }}</em><button type="button" :disabled="!canModel" @click="removeRelation(index)">删除</button></article><p v-if="!localDraft.relationshipTypes.length">当前还没有关系，请在上方创建或采用候选关系。</p></div><div v-if="semanticDiscovery?.candidateRelationships?.length" class="semantic-relation-suggestions"><span>Semantica 候选关系</span><button v-for="relation in semanticDiscovery.candidateRelationships" :key="`${relation.from}-${relation.to}`" type="button" :disabled="!canModel" @click="addSuggestedRelation(relation)"><b>{{ objectLabel(relation.from) }} — {{ relation.label }} → {{ objectLabel(relation.to) }}</b><small>{{ relation.evidenceCount }} 个关联证据 · 点击采用</small></button></div></aside></section>

    <section v-else class="review-issue-board"><header><div><span>REVIEW QUEUE</span><h3>逐项处理校对问题</h3><p>按严重程度集中展示，不需要在长页面中自行寻找。</p></div><b>{{ reviewIssues.length }} 项</b></header><div v-if="reviewIssues.length" class="review-issue-list"><button v-for="issue in reviewIssues" :key="issue.id" :class="issue.severity" @click="jumpToIssue(issue)"><i>{{ issue.severity === 'error' ? '!' : '•' }}</i><div><b>{{ issue.title }}</b><span>{{ issue.detail }}</span></div><em>{{ issue.kind === 'object' ? '定位对象' : issue.kind === 'relation' ? '定位关系' : '查看校验' }} →</em></button></div><div v-else class="review-empty"><b>✓ 当前没有待处理问题</b><span>可以保存草稿并运行结构校验。</span></div></section>

    <section class="semantic-assets-editor"><header><div><span>SEMANTIC CONTRACTS</span><h3>语义资产与治理契约</h3><p>对象与关系描述“有什么”；这里继续定义“怎么算、叫什么、质量如何、谁能看、从哪里来”。默认折叠，按需编辑。</p></div><div><b>{{ localDraft.metrics?.length || 0 }}</b> 指标 · <b>{{ localDraft.dataContracts?.length || 0 }}</b> 契约 · <b>{{ localDraft.qualityRules?.length || 0 }}</b> 质量规则</div></header>
      <details><summary>业务指标 <b>{{ localDraft.metrics?.length || 0 }}</b></summary><div class="semantic-asset-rows"><article v-for="(item, index) in localDraft.metrics" :key="item.id"><input v-model="item.label" :disabled="!canModel" aria-label="指标名称"><input v-model="item.id" :disabled="!canModel" aria-label="指标编码"><select v-model="item.grain" :disabled="!canModel"><option v-for="object in localDraft.objectTypes" :key="object.id" :value="object.id">粒度：{{ object.label }}</option></select><select v-model="item.aggregation" :disabled="!canModel"><option>count</option><option>sum</option><option>avg</option><option>min</option><option>max</option></select><input v-model="item.expression" :disabled="!canModel" aria-label="计算表达式"><button :disabled="!canModel" @click="removeSemanticAsset('metrics', index)">删除</button></article><button :disabled="!canModel" @click="addSemanticAsset('metrics')">＋ 新指标</button></div></details>
      <details><summary>业务术语 <b>{{ localDraft.glossaryTerms?.length || 0 }}</b></summary><div class="semantic-asset-rows"><article v-for="(item, index) in localDraft.glossaryTerms" :key="item.id"><input v-model="item.term" :disabled="!canModel" aria-label="术语"><select v-model="item.objectType" :disabled="!canModel"><option v-for="object in localDraft.objectTypes" :key="object.id" :value="object.id">{{ object.label }}</option></select><input v-model="item.definition" :disabled="!canModel" aria-label="定义"><input v-model="item.steward" :disabled="!canModel" aria-label="维护部门"><button :disabled="!canModel" @click="removeSemanticAsset('glossaryTerms', index)">删除</button></article><button :disabled="!canModel" @click="addSemanticAsset('glossaryTerms')">＋ 新术语</button></div></details>
      <details><summary>数据契约与质量规则 <b>{{ (localDraft.dataContracts?.length || 0) + (localDraft.qualityRules?.length || 0) }}</b></summary><div class="semantic-asset-rows"><article v-for="(item, index) in localDraft.dataContracts" :key="item.id"><input v-model="item.id" :disabled="!canModel" aria-label="契约编码"><input v-model="item.sourceSystem" :disabled="!canModel" aria-label="来源系统"><select v-model="item.objectType" :disabled="!canModel"><option v-for="object in localDraft.objectTypes" :key="object.id" :value="object.id">{{ object.label }}</option></select><input v-model="item.schemaVersion" :disabled="!canModel" aria-label="Schema版本"><input v-model.number="item.freshnessMinutes" type="number" :disabled="!canModel" aria-label="新鲜度分钟"><button :disabled="!canModel" @click="removeSemanticAsset('dataContracts', index)">删除</button></article><button :disabled="!canModel" @click="addSemanticAsset('dataContracts')">＋ 新契约</button><article v-for="(item, index) in localDraft.qualityRules" :key="item.id"><input v-model="item.id" :disabled="!canModel" aria-label="规则编码"><select v-model="item.objectType" :disabled="!canModel"><option v-for="object in localDraft.objectTypes" :key="object.id" :value="object.id">{{ object.label }}</option></select><input v-model="item.field" :disabled="!canModel" aria-label="字段"><select v-model="item.rule" :disabled="!canModel"><option>not_null</option><option>unique</option><option>accepted_values</option><option>freshness</option></select><select v-model="item.severity" :disabled="!canModel"><option>error</option><option>warning</option></select><button :disabled="!canModel" @click="removeSemanticAsset('qualityRules', index)">删除</button></article><button :disabled="!canModel" @click="addSemanticAsset('qualityRules')">＋ 新质量规则</button></div></details>
      <details><summary>访问策略与数据血缘 <b>{{ (localDraft.accessPolicies?.length || 0) + (localDraft.lineageEdges?.length || 0) }}</b></summary><div class="semantic-asset-rows"><article v-for="(item, index) in localDraft.accessPolicies" :key="item.id"><input v-model="item.id" :disabled="!canModel" aria-label="策略编码"><select v-model="item.objectType" :disabled="!canModel"><option v-for="object in localDraft.objectTypes" :key="object.id" :value="object.id">{{ object.label }}</option></select><select v-model="item.effect" :disabled="!canModel"><option>allow</option><option>deny</option></select><input :value="item.roles?.join('，')" :disabled="!canModel" aria-label="角色" @input="setArrayValue(item, 'roles', $event.target.value)"><input v-model="item.condition" :disabled="!canModel" aria-label="条件"><button :disabled="!canModel" @click="removeSemanticAsset('accessPolicies', index)">删除</button></article><button :disabled="!canModel" @click="addSemanticAsset('accessPolicies')">＋ 新访问策略</button><article v-for="(item, index) in localDraft.lineageEdges" :key="`${item.from}-${item.to}-${index}`"><input v-model="item.from" :disabled="!canModel" aria-label="来源"><select v-model="item.to" :disabled="!canModel"><option v-for="object in localDraft.objectTypes" :key="object.id" :value="object.id">{{ object.label }}</option></select><input v-model="item.transformation" :disabled="!canModel" aria-label="转换"><input :value="item.fields?.join('，')" :disabled="!canModel" aria-label="字段血缘" @input="setArrayValue(item, 'fields', $event.target.value)"><button :disabled="!canModel" @click="removeSemanticAsset('lineageEdges', index)">删除</button></article><button :disabled="!canModel" @click="addSemanticAsset('lineageEdges')">＋ 新血缘</button></div></details>
    </section>

    </details>
    <div class="modeler-action-row">
      <div class="release-chain-copy">
        <span>GOVERNED RELEASE</span>
        <b>登记到 Semantica 的发布链</b>
        <small>{{ authoringProfile?.guidance?.[2] }}</small>
      </div>
      <div class="template-actions">
        <button class="outline-button" :disabled="!canModel" @click="saveDraft"><i>1</i><span>保存草稿</span></button>
        <button class="outline-button" :disabled="!canValidate || hasUnsavedChanges" @click="$emit('validate-draft')"><i>2</i><span>校验草稿</span></button>
        <button class="primary-button" :disabled="!canSimulate || hasUnsavedChanges || localDraft.validation?.status !== 'passed'" @click="$emit('simulate-build')"><i>3</i><span>模拟构建</span></button>
        <button class="primary-button" :disabled="!canPublish || hasUnsavedChanges || simulation?.validation?.status !== 'passed' || simulation?.status === 'published'" @click="$emit('publish')"><i>4</i><span>{{ simulation?.status === 'published' ? '已登记' : '登记模型' }}</span></button>
      </div>
    </div>
    <p v-if="message" class="template-message">{{ message }}</p>
    <div v-if="localDraft.validation" :class="['validation-board', localDraft.validation.status]"><b>草稿校验：{{ localDraft.validation.status === 'passed' ? '通过' : '待修正' }}</b><span v-for="check in localDraft.validation.checks" :key="check.name">{{ check.status === 'passed' ? '✓' : '!' }} {{ check.name }}：{{ check.detail }}</span></div>
    <section v-if="simulation?.instances" class="oa-simulation-result"><div class="meta-board-title"><div><span>SIMULATED INSTANTIATION</span><b>OA 模型实例化结果</b></div><small>{{ simulation.builtAt }} · {{ simulation.builtBy }}</small></div><div class="simulation-graph"><article v-for="node in simulation.instances.nodes" :key="node.id" :class="node.state"><span>{{ node.type }}</span><b>{{ node.label }}</b></article></div><div :class="['validation-board', simulation.validation?.status]"><b>实例化校验：{{ simulation.validation?.status === 'passed' ? '通过' : '未通过' }}</b><span v-for="check in simulation.validation?.checks || []" :key="check.name">{{ check.status === 'passed' ? '✓' : '!' }} {{ check.name }}：{{ check.detail }}</span></div><div v-if="simulation.semanticValidation || simulation.semanticDeployment" :class="['semantic-deployment', simulation.semanticDeployment?.status || simulation.semanticValidation?.status]"><b>Semantica 模型登记：{{ simulation.semanticDeployment?.status === 'published' ? '已发布' : simulation.semanticValidation?.status === 'passed' ? '定义校验通过，待发布' : '未验证' }}</b><span v-if="simulation.semanticDeployment">{{ simulation.semanticDeployment.deployment?.objectCount || 0 }} 个对象 · {{ simulation.semanticDeployment.deployment?.relationshipCount || 0 }} 条关系 · 指纹 {{ simulation.semanticDeployment.deployment?.fingerprint }}</span><span v-else>Semantica 已校验对象锚点、主键、来源系统与关系引用。</span></div></section>
  </section>
</template>

<style scoped>
.domain-editor{display:grid;gap:8px;padding:12px;border:1px solid #315764;border-radius:8px;margin:10px 0}.domain-editor input{max-width:100%;box-sizing:border-box}.diagnostic-editor{display:grid;gap:10px;margin:12px 0;padding:12px;border:1px solid #d7aa63;border-radius:8px}.diagnostic-editor textarea{min-height:160px;width:100%;box-sizing:border-box;font-family:monospace}.diagnostic-editor button{padding:8px}
